  "a_sentences": [
    {
      "a_text": "P1 La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en confirmant la décision de refus de prestations de l'intimée.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 La personne assurée doit respecter l'obligation de diminuer le dommage, y compris en cas de syndrome de dépendance.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 En cas de syndrome de dépendance, l'assurance-invalidité peut ordonner une abstinence aux substances ou un traitement de sevrage.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 En cas de refus de se conformer aux mesures ordonnées, une réduction ou une suppression des prestations est admissible après mise en demeure et délai de réflexion.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 La juridiction cantonale a confirmé à juste titre que l'intimée pouvait ordonner une abstinence et refuser les prestations après l'échec des deux tentatives de sevrage.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Le fait que la personne assurée ait interrompu deux traitements ne lui est d'aucun secours, car les expertises indiquent qu'un succès durable nécessite souvent plusieurs tentatives.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Selon les constatations non contestées de l'expertise, plusieurs tentatives sont nécessaires pour atteindre un résultat thérapeutique durable dans les cas de dépendance sévère.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Le Tribunal fédéral rejette le recours comme manifestement infondé.",
      "b_propositions": ["P8"]
    }
  ]
}
